            "content": "Keep reverse-proxy stream timeouts aligned with your OmniRoute timeout env vars. If you raise\r\n`FETCH_TIMEOUT_MS` / `STREAM_IDLE_TIMEOUT_MS`, raise `proxy_read_timeout` / `proxy_send_timeout`\r\nabove the same threshold."
